CONTEXT={
 'CORE_RESOLUTION_PLAYTEST.md':['Which rule applies','Rolls','Resolve a damage event','Zero HP and recovery'],
 'COMBAT_ACTION_PLAYTEST.md':None,
 'CHARACTER_CREATION_PLAYTEST.md':['Abilities and training','Gain a level','Multiclass entry and class features','One shared RP pool','Shared strain, recovery and concentration'],
 'CHARACTER_FOUNDATION_TABLES.md':['Ability-check skills'],
 'EQUIPMENT_ACQUISITION_PLAYTEST.md':['Armor and shields','Hands and focuses','Weapons and ammunition','Carrying and containers','Fit and size'],
 'CONTROL_STATES_PLAYTEST.md':['Records, clocks and precedence','Speed arbitration','Marks and one-use components','Compulsion, action denial and initiative'],
 'SPELL_INTEGRATION_RULES.md':['Select a spell','Resolve a cast at the table','Counterspell checks and interruption','Components, summons and ongoing effects','Mark Omen and Fate Coin: reviewed spell-specific rerolls'],
 'CREATURE_LIFECYCLE_PLAYTEST.md':['At the table','Different kinds of creature life','Stats and ownership','Ranger\'s persistent bond'],
 'BUFFER_FEAT_PLAYTEST.md':['Shared rules','Empowered Summoning — Magic; Charisma14+'],
 'CONDITIONS_PLAYTEST.md':['Blinded','Grappled','Prone','Incapacitated','Frightened']}
COUNTERPARTS=['war_caster','battleMage','magic_initiate_bard','magic_initiate_cleric','magic_initiate_druid','magic_initiate_sorcerer','magic_initiate_warlock','magic_initiate_wizard','riposte','disarming_blow','cleaving_momentum','power_attack','shield_bash','shield_expert','precise_shot','unshakeable','battlefield_commander','battlefield_tactician','empowered_summoning','beast_whisperer','beast_lore','weapon_finesse','weapon_mastery']

def main():
    protected={}
    def read(p):protected[p.relative_to(GAME).as_posix()]=sha(p);return json.loads(p.read_text(encoding='utf-8-sig'))
    p=ROOT/'src/data/feats.js';raw=json.JSONDecoder().raw_decode(p.read_text(encoding='utf-8-sig').split('export const feats = ',1)[1])[0];protected[p.relative_to(GAME).as_posix()]=sha(p);by={x['id']:x for x in raw}
    reviewed=set(read(ROOT/'data/public/feat_playtests/manifest.json')['operationalIds']);routed={z['featId'] for n in ['CRAFTING_FEAT_INTERFACE','COMBAT_FEAT_SOURCE','SKILL_FEAT_SOURCE','MAGIC_CORE_FEAT_SOURCE','MAGIC_EXTENDED_FEAT_SOURCE','HERITAGE_MUTATION_FEAT_SOURCE','GENERAL_DEFENSE_FEAT_SOURCE','GENERAL_EXPLORATION_FEAT_SOURCE'] for z in read(AUDIT/(n+'_PREPARATION.json'))['selectedFeats']};pending=read(AUDIT/'REMAINING_FEAT_CATALOG_PREPARATION.json')
    selected=[x for x in raw if x['id'] not in reviewed|routed];assert len(selected)==58 and {x['id'] for x in selected}==set(QUESTIONS) and len(routed)==269
    counterparts=[{'sourceObject':by[id],'operationalReviewed':id in reviewed,'scope':'full dependency source; no extra approval or identity merge'} for id in COUNTERPARTS]
    magic=read(AUDIT/'MAGIC_CORE_FEAT_SOURCE_PREPARATION.json');magic_dependencies={k:magic[k] for k in ['currentClassIdentities','currentClassProgression','currentRankCosts','lowRankClassChoicePools']}
    ancestry=read(ROOT/'data/playtest/ancestry_background_candidate.json');ancestry_matches=[a for a in ancestry['ancestries'] if a['name'] in ('Elf','Orc')]
    class_sources=[];named_maneuver_matches=[];classnames=[]
    for p in sorted((ROOT/'data/public/class_playtests').glob('*.json')):
        d=json.loads(p.read_text(encoding='utf-8-sig'))
        if 'cards' not in d:continue
        protected[p.relative_to(GAME).as_posix()]=sha(p);classnames.append(d['class'])
        for c in d['cards']:
            if re.search(r'Battle Master|superiority di(?:e|ce)',json.dumps(c),re.I):named_maneuver_matches.append({'file':p.relative_to(GAME).as_posix(),'card':c})
            if c['id'] in ('ranger.hero.warder.beast-companion','soldier.arch.coordinated-maneuver'):
                class_sources.append({'file':p.relative_to(GAME).as_posix(),'card':c,'engine':d['engine'],'status':d['status'],'scope':'complete comparison card and engine; no feat acquisition or full class approval inferred'})
    excerpts=[]
    for name,heads in CONTEXT.items():
        p=ROOT/'docs/mechanics'/name;t=p.read_text(encoding='utf-8');protected[p.relative_to(GAME).as_posix()]=sha(p)
        for h in heads or [None]:excerpts.append({'file':p.relative_to(GAME).as_posix(),'sha256':sha(p),'heading':h or 'entire guide','exactText':t if h is None else section(t,h)})
    rows=[{'featId':x['id'],'questionId':f'GC-{i+1:02}','sourceObject':x,'sourceObjectSha256':digest(x),'fullClauseQuestion':QUESTIONS[x['id']],'currentOperationalStatus':'full-feat-review-pending'} for i,x in enumerate(selected)]
    checks=[('335 source registry byte equality',len(raw)==335 and (ROOT/'src/data/feats.js').read_bytes()==(GAME/'src/data/feats.js').read_bytes()),('327 full pending originals retained',[x for x in raw if x['id'] not in reviewed]==[z['sourceObject'] for z in pending['records']]),('58 exact remaining General identities',len(rows)==58 and all(z['sourceObject']['type']=='General' for z in rows)),('Every complete source has individual full-clause question',all(len(z['fullClauseQuestion'])>150 and z['sourceObjectSha256']==digest(z['sourceObject']) for z in rows)),('No overlap with269 prepared and8 reviewed',set(QUESTIONS).isdisjoint(routed|reviewed)),('All327 pending sources now routed',len(routed|set(QUESTIONS))==327 and len(reviewed)==8),('Full counterparts preserve source identities',len(counterparts)==23 and all(z['sourceObject']==by[z['sourceObject']['id']] for z in counterparts)),('Two exact class comparison cards and engine records',len(class_sources)==2),('Exact Elf and Orc ancestry records',len(ancestry_matches)==2),('All guide excerpts exact',all(z['exactText'] in (GAME/z['file']).read_text(encoding='utf-8') for z in excerpts)),('All protected inputs unchanged',all(sha(GAME/q)==h for q,h in protected.items()))]
    assert all(v for _,v in checks),[n for n,v in checks if not v]
    counts={'sourceFeats':335,'operationalReviewed':8,'pending':327,'selectedGeneralCombat':58,'counterparts':23,'reviewedCounterparts':sum(z['operationalReviewed'] for z in counterparts),'governingExcerpts':len(excerpts),'classComparisonCards':len(class_sources),'classCatalogsSearched':len(classnames),'namedBattleMasterSuperiorityCardMatches':len(named_maneuver_matches),'pendingSourcePrepared':327,'otherPendingFocusedPreparation':0}
    data={'status':'prepared-not-sent; full-source questions only','sourceFileSha256':sha(ROOT/'src/data/feats.js'),'selectedFeats':rows,'counterpartSources':counterparts,'magicInitiateDependencies':magic_dependencies,'exactAncestryMatches':ancestry_matches,'classComparisonSources':class_sources,'namedManeuverSearch':{'scope':'all current class-card JSON; exact Battle Master/superiority die-or-dice phrases only; absence here is not absence throughout historical folders','classIdentities':classnames,'matches':named_maneuver_matches},'currentGoverningExcerpts':excerpts,'counts':counts,'checks':[{'name':n,'pass':v} for n,v in checks],'protectedFiles':protected,'featsApproved':0,'sourceInformationDeleted':0,'newRules':False,'cosmology':'post-push only','futureDispatchRequirement':'Recheck current reviewed dependencies,including Jewelcrafting roll-event/charge decisions after its pending exact verdict. Source preparation does not approve any final feat.'}
    dump(AUDIT/'GENERAL_COMBAT_FEAT_SOURCE_PREPARATION.json',data)
    lines=['# General combat, senses and companion feat sources','',data['status'],'','These58 entries are the final unprepared identities in the335-feat source registry. Every original remains distinct,including Blind Fight/Blind Fighting,Alert/Alertness andgeneric/specific Magic Initiate. Complete source-based questions address extra attacks/reactions,rerolls,mounted/companion rules and incomplete dependencies. This is preparation,not completion of all feats.','',f"The actual current17-class card search found {len(named_maneuver_matches)} exact Battle Master/superiority-die phrase matches; search scope and full matching cards are retained. Two actual Ranger/Soldier comparison cards and engines do not automatically supply Martial Adept or Animal Companion acquisition. Actual Magic Initiate choice pools retain absent Sorcerer/Warlock lists. Elf/Orc originals are present; no half-ancestry alias is invented.",'','| Case | Source identity | Full-clause question |','|---|---|---|']
    lines += [f"| {z['questionId']} | {z['sourceObject']['name']} ({z['featId']}) | {z['fullClauseQuestion']} |" for z in rows]
    lines+=['','All327 pending feats now have focused full-source questions across nine packets; eight remain operationally reviewed. These packets are unsent. Broader interaction completion, authoring, exact review and human balance remain separate. Finish active Jewelcrafting exact review before dispatching another conference. No source deletion, push or cosmology review.',''];audit='\n'.join(lines);write(AUDIT/'GENERAL_COMBAT_FEAT_SOURCE_AUDIT.md',audit)
    packet='\n\n'.join(['PREPARED GENERAL COMBAT/SENSES/COMPANION SOURCE CONFERENCE — NOT SENT.58 complete originals and individual questions with actual source dependencies. Do not import external rules,merge identities or treat historical flags as new approval. Rebase governing dependencies at dispatch; cosmology remains post-push.',audit,'COMPLETE SOURCE AND GOVERNING EVIDENCE',json.dumps(data,ensure_ascii=False,separators=(',',':'))]);p=AUDIT/'CODEX_GENERAL_COMBAT_FEAT_SOURCE_PREPARED.txt';write(p,packet)
    status={'status':'prepared-not-sent','packetFile':p.name,'characters':len(packet),'packetSha256':sha(p),'counts':counts,'checkCount':len(checks),'protectedFilesUnchanged':len(protected),'featsApproved':0,'sourceInformationDeleted':0,'cosmology':'post-push only'};dump(AUDIT/'GENERAL_COMBAT_FEAT_SOURCE_STATUS.json',status);print(json.dumps(status))

if __name__=='__main__':main()
